// forecast's simple methods: meanf, naive, snaive, rwf, ses, holt, hw, thetaf, croston, stlf / stlm and tslm. Written
// for rStats.js from the behaviour specification oracle/tsmeta-behaviour.md ("Simple methods and small functions") with
// the details found in experiments/tsmeta120-log.md (items 28-35, 47, 51). No R or package source was read.
import { qnorm } from "../distributions/normal.js";
import { qt } from "../distributions/t.js";
import { lm } from "../models/lm.js";
import { ets, etsFixedInitial, forecastEts } from "./ets.js";
import { decompose } from "./statsTs.js";
import { mstl } from "./stl.js";
import { centred, powerOfTwoScale, shiftReference, standardise } from "./scale.js";
import { tsInput } from "./input.js";
// Generated by `node scripts/option-keys.mjs --write` from the option types; do not edit (begin)
import { checkOptions } from "../internal/checkOptions.js";
const MEANF_KEYS = ["h", "level"];
const RWF_KEYS = ["h", "drift", "level", "lag"];
const NAIVE_KEYS = ["h", "level"];
const SNAIVE_KEYS = ["frequency", "h", "level"];
const SES_KEYS = ["h", "level", "initial", "alpha"];
const HOLT_KEYS = ["h", "level", "damped", "exponential", "initial"];
const HW_KEYS = ["frequency", "h", "level", "seasonal", "damped", "initial"];
const THETAF_KEYS = ["frequency", "h", "level"];
const CROSTON_KEYS = ["h", "alpha", "type"];
const STLF_KEYS = ["frequency", "h", "level"];
const TSLM_KEYS = ["frequency", "trend", "season"];
const meanOf = (v) => v.reduce((a, b) => a + b, 0) / v.length;
const sdOf = (v) => { const m = meanOf(v); return Math.sqrt(v.reduce((a, b) => a + (b - m) ** 2, 0) / (v.length - 1)); };
const intervals = (mean, se, level, q) => ({
    lower: mean.map((m, i) => level.map((l) => m - q(l) * se[i])), upper: mean.map((m, i) => level.map((l) => m + q(l) * se[i])),
});
const zq = (l) => qnorm(0.5 + l / 200);
/**
 * Forecasts by the mean (forecast's `meanf()`): intervals mean +- qt(level, n - 1) sd(y) sqrt(1 + 1/n).
 * Equivalent to `forecast::meanf()` in R.
 *
 * @category Time series
 */
export function meanf(y, options = {}) {
    checkOptions(options, MEANF_KEYS, "meanf"); // generated: option-keys.mjs
    const h = options.h ?? 10;
    const level = [...(options.level ?? [80, 95])];
    const x = tsInput(y, "meanf", { missing: "allow" }).filter(Number.isFinite);
    const n = x.length;
    // sd of the series divided by a power of two c (exact), times c: no overflow of the squares
    const c = powerOfTwoScale(x);
    const mu = meanOf(x);
    const s = c * sdOf(x.map((v) => v / c)) * Math.sqrt(1 + 1 / n);
    const mean = new Array(h).fill(mu);
    const iv = intervals(mean, new Array(h).fill(s), level, (l) => qt(0.5 + l / 200, n - 1));
    return { mean, ...iv, level, fitted: y.map(() => mu), residuals: y.map((v) => v - mu), method: "Mean" };
}
/**
 * Random walk forecasts (forecast's `rwf()`), with a drift (y_n - y_1)/(n - 1) when `drift`. sigma = sqrt(mean(res^2))
 * without a drift, sd(res) with one; se_h = sigma sqrt(h) or sigma sqrt(h (1 + h/(n - 1))).
 * Equivalent to `forecast::rwf()` in R.
 *
 * @category Time series
 */
export function rwf(y, options = {}) {
    checkOptions(options, RWF_KEYS, "rwf"); // generated: option-keys.mjs
    const h = options.h ?? 10;
    const level = [...(options.level ?? [80, 95])];
    const drift = options.drift ?? false;
    const lag = options.lag ?? 1;
    // a missing value is skipped by the residual sd; at least lag + 1 values (R fails at n <= lag; log 107)
    y = tsInput(y, "rwf", { missing: "allow", minLength: lag + 1 });
    // with missing values as R's (log 108): the fitted value is the last observed value of the same season (y_{t - j lag},
    // the smallest j with it observed), and the drift the mean of those steps (equal to 1e-16 in the intervals)
    const n = y.length;
    const prev = y.map((_, t) => { for (let k = t - lag; k >= 0; k -= lag)
        if (!Number.isNaN(y[k]))
            return y[k]; return NaN; });
    const steps = y.map((v, t) => v - prev[t]).filter(Number.isFinite);
    const b = drift ? steps.reduce((a, v) => a + v, 0) / steps.length : 0;
    const fitted = prev.map((v) => v + b);
    const residuals = y.map((v, t) => v - fitted[t]);
    const res = residuals.filter(Number.isFinite);
    // on the residuals divided by a power of two c (exact), times c: no overflow of the squares
    const c = powerOfTwoScale(res);
    const rs = res.map((r) => r / c);
    const sigma = c * (drift ? sdOf(rs) : Math.sqrt(meanOf(rs.map((r) => r * r))));
    const mean = Array.from({ length: h }, (_, i) => (lag === 1 ? y[n - 1] + (i + 1) * b : y[n - lag + (i % lag)]));
    const se = Array.from({ length: h }, (_, i) => {
        const k = i + 1;
        if (lag > 1)
            return sigma * Math.sqrt(Math.floor((k - 1) / lag) + 1);
        return drift ? sigma * Math.sqrt(k * (1 + k / steps.length)) : sigma * Math.sqrt(k);
    });
    return { mean, ...intervals(mean, se, level, zq), level, fitted, residuals,
        method: lag > 1 ? "Seasonal naive method" : drift ? "Random walk with drift" : "Random walk" };
}
/**
 * Naive forecasts (forecast's `naive()`): {@link rwf} without a drift. Equivalent to `forecast::naive()` in R.
 *
 * @category Time series
 */
export function naive(y, options = {}) {
    checkOptions(options, NAIVE_KEYS, "naive"); // generated: option-keys.mjs
    return { ...rwf(y, options), method: "Naive method" };
}
/**
 * Seasonal naive forecasts (forecast's `snaive()`): y_{n - m + ...}, se_h = sigma sqrt(floor((h - 1)/m) + 1). Equivalent to `forecast::snaive()` in R.
 *
 * @category Time series
 */
export function snaive(y, options) {
    checkOptions(options, SNAIVE_KEYS, "snaive"); // generated: option-keys.mjs
    return rwf(y, { h: options.h ?? 2 * options.frequency, lag: options.frequency, ...(options.level ? { level: options.level } : {}) });
}
function fromEts(fit, h, level, method, simple = false) {
    // initial = "simple": R's sigma2 is SSE / n (log 91). R's hw(initial = "simple") also puts its Holt-Winters beta*
    // (beta = alpha beta*) into the ets variance as if it were beta; rStats.js uses the model's beta (a departure)
    if (simple)
        fit.sigma2 = fit.residuals.reduce((a, v) => a + v * v, 0) / fit.x.length;
    const fc = forecastEts(fit, { h, level });
    // as R's: the model's innovations (relative for multiplicative errors) for an ets fit, y - fitted with
    // initial = "simple" (log 91)
    const residuals = simple ? fit.x.map((v, i) => v - fit.fitted[i]) : fit.residuals.slice();
    return { mean: fc.mean, lower: fc.lower, upper: fc.upper, level, fitted: fit.fitted, residuals, method, model: fit };
}
/**
 * Simple exponential smoothing (forecast's `ses()`): ets(y, "ANN"), or with `initial: "simple"` the level started at
 * y_1 and alpha minimising the one-step SSE.
 * Equivalent to `forecast::ses()` in R.
 *
 * @category Time series
 */
export function ses(y, options = {}) {
    checkOptions(options, SES_KEYS, "ses"); // generated: option-keys.mjs
    const h = options.h ?? 10;
    const level = [...(options.level ?? [80, 95])];
    const fixed = options.alpha !== undefined ? { alpha: options.alpha } : {};
    const fit = options.initial === "simple"
        ? etsFixedInitial(y, { error: "A", trend: "N", damped: false, season: "N", m: 1 }, { l: y[0] }, fixed, "mse", "simple")
        : ets(y, { model: "ANN", ...fixed });
    return fromEts(fit, h, level, "Simple exponential smoothing", options.initial === "simple");
}
/**
 * Holt's linear trend method (forecast's `holt()`): ets AAN (AAdN damped, MMN exponential); `initial: "simple"`
 * starts at l = y_1, b = y_2 - y_1.
 * Equivalent to `forecast::holt()` in R.
 *
 * @category Time series
 */
export function holt(y, options = {}) {
    checkOptions(options, HOLT_KEYS, "holt"); // generated: option-keys.mjs
    const h = options.h ?? 10;
    const level = [...(options.level ?? [80, 95])];
    const damped = options.damped ?? false;
    const expo = options.exponential ?? false;
    const spec = { error: expo ? "M" : "A", trend: expo ? "M" : "A", damped, season: "N", m: 1 };
    const fit = options.initial === "simple"
        ? etsFixedInitial(y, spec, expo ? { l: y[0], b: y[1] / y[0] } : { l: y[0], b: y[1] - y[0] }, {}, "mse", "simple")
        : ets(y, { model: expo ? "MMN" : "AAN", damped });
    const method = damped ? (expo ? "Damped Holt's method with exponential trend" : "Damped Holt's method") : expo ? "Holt's method with exponential trend" : "Holt's method";
    return fromEts(fit, h, level, method, options.initial === "simple");
}
/**
 * Holt-Winters seasonal method (forecast's `hw()`): ets AAA or MAM (damped: AAdA, MAdM); `initial: "simple"` starts at
 * l = mean(y[1:m]), b = (mean(y[m+1:2m]) - mean(y[1:m]))/m, s = y[1:m] - l (or / l).
 * Equivalent to `forecast::hw()` in R.
 *
 * @category Time series
 */
export function hw(y, options) {
    checkOptions(options, HW_KEYS, "hw"); // generated: option-keys.mjs
    const m = options.frequency;
    const h = options.h ?? 2 * m;
    const level = [...(options.level ?? [80, 95])];
    const mult = options.seasonal === "multiplicative";
    const damped = options.damped ?? false;
    // R's minimum (log 109: "I need at least m + 3 observations to estimate seasonality", 15 for m = 12, 7 for m = 4)
    if (y.length < m + 3)
        throw new RangeError(`hw: at least ${m + 3} observations are needed to estimate seasonality (got ${y.length})`);
    const spec = { error: mult ? "M" : "A", trend: "A", damped, season: mult ? "M" : "A", m };
    let fit;
    if (options.initial === "simple") {
        const l = meanOf(y.slice(0, m));
        const b = (meanOf(y.slice(m, 2 * m)) - l) / m;
        // s1 = the most recent (period m), ..., sm = period 1
        const s = y.slice(0, m).map((v) => (mult ? v / l : v - l)).reverse();
        fit = etsFixedInitial(y, spec, { l, b, s }, {}, "mse", "simple");
    }
    else
        fit = ets(y, { frequency: m, model: mult ? "MAM" : "AAA", damped });
    const method = `${damped ? "Damped " : ""}Holt-Winters' ${mult ? "multiplicative" : "additive"} method`;
    return fromEts(fit, h, level, method, options.initial === "simple");
}
/** The lag-k autocorrelations (mean removed, over n). */
function acfValues(x0, maxLag) {
    const x = standardise(centred(x0));
    const n = x.length;
    const m = meanOf(x);
    const c0 = x.reduce((a, v) => a + (v - m) ** 2, 0) / n;
    return Array.from({ length: maxLag }, (_, k) => { let s = 0; for (let t = k + 1; t < n; t++)
        s += (x[t] - m) * (x[t - k - 1] - m); return s / n / c0; });
}
/**
 * The theta method (forecast's `thetaf()`): a seasonality test |r_m| > qnorm(0.95) sqrt((1 + 2 sum_{i<m} r_i^2)/n), a
 * multiplicative decompose when seasonal, ses by MSE, mean = ses mean + b/2 (h - 1 + 1/alpha - (1 - alpha)^n / alpha)
 * with b the slope of lm(y ~ t), reseasonalised. Departs from R when seasonal: the interval bounds are reseasonalised
 * (R adds the adjusted-scale width to the reseasonalised mean) and the residuals are y - fitted (R's are on the
 * adjusted scale); the user's decision, log 91-92.
 * Equivalent to `forecast::thetaf()` in R.
 *
 * @category Time series
 */
export function thetaf(y, options = {}) {
    checkOptions(options, THETAF_KEYS, "thetaf"); // generated: option-keys.mjs
    const m = options.frequency ?? 1;
    const h = options.h ?? (m > 1 ? 2 * m : 10);
    const level = [...(options.level ?? [80, 95])];
    // missing values: an error, as R's (log 107)
    y = tsInput(y, "thetaf");
    const n = y.length;
    let seasonal = false;
    if (m > 1 && n >= 2 * m) {
        const r = acfValues(y, m);
        const stat = Math.abs(r[m - 1]);
        const crit = qnorm(0.95) * Math.sqrt((1 + 2 * r.slice(0, m - 1).reduce((a, v) => a + v * v, 0)) / n);
        seasonal = stat > crit;
    }
    let adj = y.slice();
    let sidx = [];
    if (seasonal) {
        const d = decompose(y, { frequency: m, type: "multiplicative" });
        sidx = d.figure;
        adj = y.map((v, i) => v / sidx[i % m]);
    }
    const fit = ets(adj, { model: "ANN", optCrit: "mse" });
    const alpha = fit.par.alpha;
    const fc = forecastEts(fit, { h, level });
    const b = lm(adj.map((_, t) => [t + 1]), adj, {}).coefficients[1];
    const add = Array.from({ length: h }, (_, i) => (b / 2) * (i + 1 - 1 + 1 / alpha - (1 - alpha) ** n / alpha));
    const seasonOf = (k) => (seasonal ? sidx[(n + k) % m] : 1);
    const mean = fc.mean.map((v, i) => (v + add[i]) * seasonOf(i));
    const lower = fc.lower.map((row, i) => row.map((v) => (v + add[i]) * seasonOf(i)));
    const upper = fc.upper.map((row, i) => row.map((v) => (v + add[i]) * seasonOf(i)));
    const fitted = fit.fitted.map((v, i) => v * (seasonal ? sidx[i % m] : 1));
    return { mean, lower, upper, level, fitted, residuals: y.map((v, i) => v - fitted[i]), method: "Theta" };
}
/**
 * Croston's method for intermittent demand (forecast's `croston()`): SES with alpha on the non-zero demands and on the
 * intervals between them (counted from time 0), each started at its first value; forecast k z / p with k = 1 (croston),
 * 1 - alpha/2 (sba) or 1 - alpha/(2 - alpha) (sbj). No intervals. Departs from R when the last observation is a
 * demand: R's forecast is the state before it (the last fitted value, the last observation unused; log 91), rStats.js
 * forecasts from the state after it.
 * Equivalent to `forecast::croston()` in R.
 *
 * @category Time series
 */
export function croston(y, options = {}) {
    checkOptions(options, CROSTON_KEYS, "croston"); // generated: option-keys.mjs
    const h = options.h ?? 10;
    const alpha = options.alpha ?? 0.1;
    const type = options.type ?? "croston";
    const k = type === "croston" ? 1 : type === "sba" ? 1 - alpha / 2 : 1 - alpha / (2 - alpha);
    // at least two demands (the first starts the smoothing of the sizes and of the intervals), as R's; missing values
    // an error (log 107)
    y = tsInput(y, "croston");
    if (y.filter((v) => v !== 0).length < 2)
        throw new RangeError("croston: at least two non-zero values are needed");
    const n = y.length;
    const fitted = new Array(n).fill(NaN);
    let z = NaN, p = NaN;
    let last = 0; // time of the last demand (time 0 before the series)
    for (let t = 0; t < n; t++) {
        if (t > 0)
            fitted[t] = Number.isNaN(z) ? 0 : (k * z) / p;
        if (y[t] !== 0) {
            const interval = t + 1 - last;
            last = t + 1;
            if (Number.isNaN(z)) {
                z = y[t];
                p = interval;
            }
            else {
                z += alpha * (y[t] - z);
                p += alpha * (interval - p);
            }
        }
    }
    const f = Number.isNaN(z) ? 0 : (k * z) / p;
    return { mean: new Array(h).fill(f), fitted, method: "Croston's method" };
}
/**
 * STL + ETS forecasts (forecast's `stlf()`): mstl(y), forecast(ets(seasonally adjusted, "ZZN")), plus the last cycle of
 * the seasonal component repeated.
 * Equivalent to `forecast::stlf()` in R.
 *
 * @category Time series
 */
export function stlf(y, options) {
    checkOptions(options, STLF_KEYS, "stlf"); // generated: option-keys.mjs
    const m = options.frequency;
    const h = options.h ?? 2 * m;
    const level = [...(options.level ?? [80, 95])];
    const d = mstl(y, { frequency: m });
    const seas = d.seasonal ?? new Array(y.length).fill(0);
    const adj = y.map((v, i) => v - seas[i]);
    const fit = ets(adj, { model: "ZZN" });
    const fc = forecastEts(fit, { h, level });
    // without a seasonal component (fewer than two periods: mstl's trend only) the forecasts are not reseasonalised
    const n = y.length;
    const lastCycle = seas.slice(n - m);
    const sAt = (i) => (d.seasonal ? lastCycle[i % m] : 0);
    const fitted = fit.fitted.map((v, i) => v + seas[i]);
    return { mean: fc.mean.map((v, i) => v + sAt(i)), lower: fc.lower.map((r, i) => r.map((v) => v + sAt(i))), upper: fc.upper.map((r, i) => r.map((v) => v + sAt(i))),
        level, fitted, residuals: y.map((v, i) => v - fitted[i]), method: `STL +  ${fit.method}`, model: fit };
}
/**
 * Linear regression on a trend (1..n) and seasonal dummies (forecast's `tslm(y ~ trend + season)`), the first season
 * the baseline.
 * Equivalent to `forecast::tslm()` in R.
 *
 * @category Time series
 */
export function tslm(y, options = {}) {
    checkOptions(options, TSLM_KEYS, "tslm"); // generated: option-keys.mjs
    const m = options.frequency ?? 1;
    const useT = options.trend ?? true;
    const useS = (options.season ?? true) && m > 1;
    const row = (t) => [...(useT ? [t + 1] : []), ...(useS ? Array.from({ length: m - 1 }, (_, k) => (t % m === k + 1 ? 1 : 0)) : [])];
    y = tsInput(y, "tslm", { missing: "allow", minLength: 2 });
    // fitted to (y - r) / c (r a large common value, c a power of two; exact) and mapped back: the sums of squares stay in
    // range at 1e+-300 and the seasonal coefficients keep their digits at y + 1e15 (log 110)
    const r0 = shiftReference(y);
    const c0 = powerOfTwoScale(y.map((v) => v - r0));
    const n = y.length;
    const X = y.map((_, t) => row(t));
    const fs = lm(X, y.map((v) => (v - r0) / c0), {});
    const f = { coefficients: fs.coefficients.map((b, j) => b * c0 + (j === 0 ? r0 : 0)), fittedValues: fs.fittedValues.map((v) => v * c0 + r0),
        residuals: fs.residuals.map((v) => v * c0) };
    const names = ["(Intercept)", ...(useT ? ["trend"] : []), ...(useS ? Array.from({ length: m - 1 }, (_, k) => `season${k + 2}`) : [])];
    const Xf = X.map((r) => [1, ...r]);
    const k = Xf[0].length;
    // (X'X)^{-1} for the prediction variances
    const A = Array.from({ length: k }, (_, i) => Array.from({ length: k }, (_, j) => Xf.reduce((s, r) => s + r[i] * r[j], 0)));
    const inv = invert(A);
    const s2 = fs.residuals.reduce((a, v) => (Number.isNaN(v) ? a : a + v * v), 0) / (n - k);
    return {
        coefficients: f.coefficients, coefficientNames: names, fitted: f.fittedValues, residuals: f.residuals,
        forecast: (h, lev = [80, 95]) => {
            const rows = Array.from({ length: h }, (_, i) => [1, ...row(n + i)]);
            const mean = rows.map((r) => r0 + c0 * r.reduce((s, v, j) => s + v * fs.coefficients[j], 0));
            const se = rows.map((r) => c0 * Math.sqrt(s2 * (1 + r.reduce((s, v, i) => s + v * r.reduce((s2_, w, j) => s2_ + inv[i][j] * w, 0), 0))));
            const level = [...lev];
            return { mean, ...intervals(mean, se, level, (l) => qt(0.5 + l / 200, n - k)), level };
        },
    };
}
function invert(A) {
    const k = A.length;
    const M = A.map((r, i) => [...r, ...Array.from({ length: k }, (_, j) => (i === j ? 1 : 0))]);
    for (let i = 0; i < k; i++) {
        let p = i;
        for (let r = i + 1; r < k; r++)
            if (Math.abs(M[r][i]) > Math.abs(M[p][i]))
                p = r;
        [M[i], M[p]] = [M[p], M[i]];
        const d = M[i][i];
        for (let c = 0; c < 2 * k; c++)
            M[i][c] /= d;
        for (let r = 0; r < k; r++)
            if (r !== i) {
                const f = M[r][i];
                for (let c = 0; c < 2 * k; c++)
                    M[r][c] -= f * M[i][c];
            }
    }
    return M.map((r) => r.slice(k));
}
